create table if not exists public.cash_transactions(id uuid primary key default gen_random_uuid(),transaction_date date not null default current_date,reference_no text not null,description text not null,amount numeric(18,2) not null check(amount>=0),payment_method text not null,status text not null default 'posted',created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.finance_entries(id uuid primary key default gen_random_uuid(),entry_date date not null default current_date,type text not null check(type in('income','expense')),category text not null,description text not null,amount numeric(18,2) not null check(amount>=0),reference_no text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.portal_documents(id uuid primary key default gen_random_uuid(),title text not null,category text not null,file_url text not null,audience text not null default 'public' check(audience in('public','investor','internal')),published boolean not null default false,created_by uuid references auth.users(id),created_at timestamptz not null default now());
alter table public.cash_transactions enable row level security;alter table public.finance_entries enable row level security;alter table public.portal_documents enable row level security;
create or replace function public.is_portal_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.portal_admins where user_id=auth.uid())$$;
create policy "admins manage cash" on public.cash_transactions for all to authenticated using(public.is_portal_admin()) with check(public.is_portal_admin());
create policy "admins manage finance" on public.finance_entries for all to authenticated using(public.is_portal_admin()) with check(public.is_portal_admin());
create policy "admins manage documents" on public.portal_documents for all to authenticated using(public.is_portal_admin()) with check(public.is_portal_admin());
create policy "public reads public documents" on public.portal_documents for select to anon,authenticated using(published=true and audience='public');
create policy "investors read investor documents" on public.portal_documents for select to authenticated using(published=true and audience in('public','investor') and exists(select 1 from public.investor_profiles i where i.user_id=auth.uid() and i.status='approved'));
